import { Injectable } from '@angular/core';

/**
 * Typed panel-side API client. Requests are same-origin (`/api/v1/...`) via
 * the Angular dev-server proxy (prod: nginx), so the session cookie is
 * first-party. Every mutating request echoes the readable CSRF cookie in the
 * `x-csrf-token` header (plan §5.3, §14 auth). The response shapes match the
 * committed OpenAPI document generated by `npm run gen:api` (schema.d.ts), which
 * is the single source of truth the panel binds to.
 */
@Injectable({ providedIn: 'root' })
export class ApiClient {
  private csrf(): string | null {
    const m = document.cookie.match(/(?:^|;\s*)fpm_csrf=([^;]+)/);
    return m ? decodeURIComponent(m[1]) : null;
  }

  async get<T = unknown>(path: string): Promise<T> {
    const res = await fetch(path, { credentials: 'include' });
    return this.unwrap<T>(res);
  }

  async send<T = unknown>(method: 'POST' | 'PUT' | 'PATCH' | 'DELETE', path: string, body?: unknown): Promise<T> {
    const token = this.csrf();
    const headers: Record<string, string> = { 'content-type': 'application/json' };
    if (token) headers['x-csrf-token'] = token;
    const res = await fetch(path, {
      method,
      credentials: 'include',
      headers,
      body: body === undefined ? undefined : JSON.stringify(body),
    });
    return this.unwrap<T>(res);
  }

  post<T = unknown>(path: string, body?: unknown): Promise<T> {
    return this.send<T>('POST', path, body);
  }
  put<T = unknown>(path: string, body?: unknown): Promise<T> {
    return this.send<T>('PUT', path, body);
  }

  private async unwrap<T>(res: Response): Promise<T> {
    if (res.status === 204) return undefined as T;
    const text = await res.text();
    const parsed: unknown = text ? JSON.parse(text) : null;
    if (!res.ok) {
      const body = parsed as { error?: { message?: string; code?: string } } | null;
      const msg = body?.error?.message ?? `HTTP ${res.status}`;
      // status/code ride along so callers can distinguish policy errors
      // (e.g. 503 MODULE_DISABLED) from transport failures (STT-006).
      throw Object.assign(new Error(msg), { status: res.status, code: body?.error?.code });
    }
    return parsed as T;
  }
}

export interface MeResponse {
  actor: { type: string; id: string; organization_id: string | null; org_role: string | null };
  user: { id: string; email: string; display_name: string; locale: string; timezone: string } | null;
  csrf_token: string | null;
}
